using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.UI;using TMPro;
[InitializeOnLoad]public static class WindPopupStylePolish{static WindPopupStylePolish(){EditorApplication.update+=Tick;}static void Tick(){if(!File.Exists("Temp/wind-popup-polish.flag")||Application.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating)return;File.Delete("Temp/wind-popup-polish.flag");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.isDirty)return;var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var panel=all.Single(t=>t.name=="Wind Speed Panel");var button=all.Single(t=>t.name=="Wind Speed Button");var settings=all.First(t=>t.name=="Main Settings Multiple Slider Detached");var font=settings.GetComponentsInChildren<TMP_Text>(true).First().font;foreach(var text in panel.GetComponentsInChildren<TMP_Text>(true).Concat(button.GetComponentsInChildren<TMP_Text>(true)))text.font=font;var view=panel.Find("View Turbine");var image=view.GetComponent<Image>();image.sprite=null;image.color=new Color(.16f,.16f,.16f,.745f);var border=settings.Find("Border");if(border&&!view.Find("Border")){var copy=UnityEngine.Object.Instantiate(border.gameObject,view,false);copy.name="Border";var r=(RectTransform)copy.transform;r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=Vector2.zero;r.sizeDelta=Vector2.zero;copy.transform.SetAsFirstSibling();foreach(var g in copy.GetComponentsInChildren<Graphic>(true))g.raycastTarget=false;}var highlight=button.Find("Step Highlight");if(!highlight.Find("Outline")){var outline=new GameObject("Outline",typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));outline.transform.SetParent(highlight,false);var r=(RectTransform)outline.transform;r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.sizeDelta=new Vector2(55,55);var im=outline.GetComponent<Image>();im.sprite=button.Find("Pressed/Outline").GetComponent<Image>().sprite;im.color=Color.white;im.preserveAspect=true;im.raycastTarget=false;outline.layer=button.gameObject.layer;}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}
